    {

           using var activity =  StartCallActivity("StopPollAsync", typeof(StopPoll).FullName ?? "StopPollAsync");

           try
           {
             return client.StopPollAsync(chatId, messageId, replyMarkup);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
